//! Typed provenance for harness-generated workflow drafts.
//!
//! ```text
//! SourcePassage -> Claim -> accepted Decision -> workflow step (component)
//! ```
//!
//! A workflow draft is marked harness-generated by `begin_ai_workflow_generation`,
//! which binds it to one governed run resolved from the run table — never from
//! a browser or model claim. From then on the draft cannot publish until every
//! *material* step has current staged provenance:
//!
//! - `stage_ai_workflow_node_provenance` records, per stable node key, the
//!   accepted decisions and (optionally) the human-reviewed claims that justify
//!   the step. The server computes the canonical node-content hash itself; the
//!   caller never supplies a hash, a run, a tenant or a review status.
//! - Publication rechecks every staged row (content hash, accepted decisions,
//!   current reviewed claims, dependencies, tenant scope) and binds the step
//!   into `AiArtifactComponent` through the same helpers `bind_ai_artifact_component`
//!   uses. Any failure returns `Err`, which rolls the whole publication back.
//! - There is no second lineage table: the durable record is the component
//!   `workflow-version:<version_id>` / `node:<node_key>`.
//!
//! A clone of a generated version carries its provenance forward as a fork of
//! each parent component, preserving ancestry. Changed content or links mark
//! the fork `changed`, and it cannot publish until a reviewer confirms exactly
//! the current node hash. Human-authored workflows have no generation row and
//! are untouched.
//!
//! Every reducer here is denied to generic dispatch; the trusted gateway is the
//! only intended caller of `begin`/`stage`.

use spacetimedb::{reducer, Identity, ReducerContext, SpacetimeType, Table, Timestamp};

use crate::ai::evidence_common::validate_id_list;
use crate::ai::evidence_dependency::{require_dependencies_usable, DependentKind};
use crate::ai::evidence_lineage::{
    bind_ai_artifact_component_inner, find_current_component, load_claim, require_bindable_links,
    require_reviewed_claim_links, revise_ai_artifact_component_inner, supersede_component,
    validate_component_links, AiArtifactComponent, BindAiArtifactComponentParams,
    ReviseAiArtifactComponentParams, LINK_LINKED,
};
use crate::ai::skills::ai_agent_run;
use crate::core::organization::require_company_in_organization;
use crate::helpers::{check_permission, write_audit_log_v2, AuditLogParams};
use crate::workflow::definitions::{
    canonical_node_hash, load_draft, nodes_for_version, workflow_node, workflow_version,
    WorkflowNode, WorkflowNodeKind, WorkflowVersion,
};

pub const ARTIFACT_PREFIX: &str = "workflow-version:";
pub const COMPONENT_KEY_PREFIX: &str = "node:";
pub const STAGED_CURRENT: &str = "current";
pub const STAGED_SUPERSEDED: &str = "superseded";
/// A run may be recorded as the origin of a draft only while it is live or
/// finished; a failed or cancelled run produced nothing to attribute.
const ORIGIN_RUN_STATUSES: [&str; 2] = ["running", "completed"];

// ── Tables ───────────────────────────────────────────────────────────────────

/// Marks one workflow version as harness-generated and names its governed run.
#[derive(Clone)]
#[spacetimedb::table(
    accessor = ai_workflow_generation,
    index(accessor = ai_workflow_generation_by_org, btree(columns = [organization_id]))
)]
pub struct AiWorkflowGeneration {
    #[primary_key]
    #[auto_inc]
    pub id: u64,
    pub organization_id: u64,
    pub company_id: u64,
    #[unique]
    pub workflow_version_id: u64,
    /// The governed run that produced the draft, verified against the run table.
    pub run_id: u64,
    /// The published version this draft was cloned from, when it is a revision.
    pub parent_workflow_version_id: Option<u64>,
    pub create_uid: Identity,
    pub create_date: Timestamp,
}

/// The typed, version-bound staging contract for one generated step.
#[derive(Clone)]
#[spacetimedb::table(
    accessor = ai_workflow_node_provenance,
    index(accessor = ai_workflow_node_provenance_by_org, btree(columns = [organization_id])),
    index(
        accessor = ai_workflow_node_provenance_by_version,
        btree(columns = [workflow_version_id])
    )
)]
pub struct AiWorkflowNodeProvenance {
    #[primary_key]
    #[auto_inc]
    pub id: u64,
    pub organization_id: u64,
    pub company_id: u64,
    pub workflow_version_id: u64,
    /// The draft revision the step was staged against.
    pub draft_revision: u64,
    pub node_key: String,
    /// Copied from the generation row; never accepted from a caller.
    pub run_id: u64,
    pub decision_ids: Vec<u64>,
    pub claim_ids: Vec<u64>,
    /// Canonical hash of the node's executable content when it was staged.
    pub node_content_hash: String,
    /// current | superseded
    pub status: String,
    pub create_uid: Identity,
    pub create_date: Timestamp,
}

// ── Input Params ─────────────────────────────────────────────────────────────

#[derive(SpacetimeType, Clone, Debug)]
pub struct StageAiWorkflowNodeProvenanceParams {
    pub node_key: String,
    pub decision_ids: Vec<u64>,
    pub claim_ids: Vec<u64>,
}

// ── Pure helpers ─────────────────────────────────────────────────────────────

pub fn version_artifact_ref(workflow_version_id: u64) -> String {
    format!("{ARTIFACT_PREFIX}{workflow_version_id}")
}

pub fn component_key_for(node_key: &str) -> String {
    format!("{COMPONENT_KEY_PREFIX}{node_key}")
}

/// The version id and node key a workflow-step component names, if it names
/// one in this form.
pub fn parse_step_component(artifact_ref: &str, component_key: &str) -> Option<(u64, String)> {
    let version_id = artifact_ref.strip_prefix(ARTIFACT_PREFIX)?.parse().ok()?;
    let node_key = component_key.strip_prefix(COMPONENT_KEY_PREFIX)?;
    if node_key.is_empty() {
        return None;
    }
    Some((version_id, node_key.to_string()))
}

/// A step that executes something. `Start`, `End`, `Fork` and `Join` only route
/// tokens, so a generated workflow does not need a justification for them; any
/// of them that is staged is bound like any other step.
pub fn is_material_node(kind: &WorkflowNodeKind) -> bool {
    !matches!(
        kind,
        WorkflowNodeKind::Start
            | WorkflowNodeKind::End
            | WorkflowNodeKind::Fork
            | WorkflowNodeKind::Join
    )
}

fn sorted(ids: &[u64]) -> Vec<u64> {
    let mut out = ids.to_vec();
    out.sort_unstable();
    out
}

// ── Reducers ─────────────────────────────────────────────────────────────────

/// Mark a draft as harness-generated by `run_id`. The run must exist in this
/// organization and company and be live or finished; the draft must be a draft
/// of this company. A retry naming the same run is a no-op.
#[reducer]
pub fn begin_ai_workflow_generation(
    ctx: &ReducerContext,
    organization_id: u64,
    company_id: u64,
    workflow_version_id: u64,
    expected_revision: u64,
    run_id: u64,
) -> Result<(), String> {
    if organization_id == 0 {
        return Err("organization_id must be nonzero".to_string());
    }
    check_permission(ctx, organization_id, "ai_workflow_provenance", "create")?;
    require_company_in_organization(ctx, organization_id, company_id)?;
    let version = load_draft(ctx, organization_id, workflow_version_id, expected_revision)?;
    if version.company_id != Some(company_id) {
        return Err("a generated workflow must belong to the named company".to_string());
    }
    let run = ctx
        .db
        .ai_agent_run()
        .id()
        .find(&run_id)
        .ok_or_else(|| format!("Run {run_id} not found"))?;
    if run.organization_id != organization_id || run.company_id != company_id {
        return Err(format!(
            "Run {run_id} does not belong to this organization/company"
        ));
    }
    if !ORIGIN_RUN_STATUSES.contains(&run.status.as_str()) {
        return Err(format!(
            "a {} run cannot be the origin of a generated workflow",
            run.status
        ));
    }

    if let Some(existing) = find_generation(ctx, workflow_version_id) {
        if existing.run_id == run_id {
            return Ok(());
        }
        return Err("the workflow draft is already bound to a different run".to_string());
    }
    let row = ctx
        .db
        .ai_workflow_generation()
        .insert(AiWorkflowGeneration {
            id: 0,
            organization_id,
            company_id,
            workflow_version_id,
            run_id,
            parent_workflow_version_id: None,
            create_uid: ctx.sender(),
            create_date: ctx.timestamp,
        });
    write_audit_log_v2(
        ctx,
        organization_id,
        AuditLogParams {
            company_id: Some(company_id),
            table_name: "ai_workflow_generation",
            record_id: row.id,
            action: "CREATE",
            old_values: None,
            new_values: Some(
                serde_json::json!({
                    "workflow_version_id": workflow_version_id,
                    "run_id": run_id,
                })
                .to_string(),
            ),
            changed_fields: vec!["workflow_version_id".to_string(), "run_id".to_string()],
            metadata: None,
        },
    );
    Ok(())
}

/// Stage the accepted decisions (and optional human-reviewed claims) that
/// justify one node of a generated draft. The staged row carries the node's
/// canonical content hash and the generation's run, both computed here.
///
/// Restaging identical content and links is a no-op. Restaging different
/// content or links supersedes the earlier row and, if the draft already holds
/// a component for the step (a clone), revises it so its links read `changed`
/// until a reviewer confirms them.
#[reducer]
pub fn stage_ai_workflow_node_provenance(
    ctx: &ReducerContext,
    organization_id: u64,
    company_id: u64,
    workflow_version_id: u64,
    expected_revision: u64,
    params: StageAiWorkflowNodeProvenanceParams,
) -> Result<(), String> {
    if organization_id == 0 {
        return Err("organization_id must be nonzero".to_string());
    }
    check_permission(ctx, organization_id, "ai_workflow_provenance", "create")?;
    require_company_in_organization(ctx, organization_id, company_id)?;
    let version = load_draft(ctx, organization_id, workflow_version_id, expected_revision)?;
    let generation = require_generation_scope(ctx, &version, organization_id, company_id)?;
    validate_id_list("decision_ids", &params.decision_ids)?;
    validate_id_list("claim_ids", &params.claim_ids)?;
    let node = nodes_for_version(ctx, workflow_version_id)
        .into_iter()
        .find(|node| node.node_key == params.node_key)
        .ok_or_else(|| {
            format!(
                "workflow node '{}' not found in this draft",
                params.node_key
            )
        })?;
    let node_hash = canonical_node_hash(&node)?;
    let decision_ids = sorted(&params.decision_ids);
    let claim_ids = sorted(&params.claim_ids);
    require_step_links_current(ctx, organization_id, company_id, &decision_ids, &claim_ids)?;

    let previous = current_staged(ctx, workflow_version_id, &node.node_key);
    if let Some(previous) = &previous {
        if previous.node_content_hash == node_hash
            && sorted(&previous.decision_ids) == decision_ids
            && sorted(&previous.claim_ids) == claim_ids
        {
            return Ok(());
        }
    }
    if let Some(previous) = previous {
        ctx.db
            .ai_workflow_node_provenance()
            .id()
            .update(AiWorkflowNodeProvenance {
                status: STAGED_SUPERSEDED.to_string(),
                ..previous
            });
    }
    let row = ctx
        .db
        .ai_workflow_node_provenance()
        .insert(AiWorkflowNodeProvenance {
            id: 0,
            organization_id,
            company_id,
            workflow_version_id,
            draft_revision: version.draft_revision,
            node_key: node.node_key.clone(),
            run_id: generation.run_id,
            decision_ids: decision_ids.clone(),
            claim_ids: claim_ids.clone(),
            node_content_hash: node_hash.clone(),
            status: STAGED_CURRENT.to_string(),
            create_uid: ctx.sender(),
            create_date: ctx.timestamp,
        });

    // A cloned draft already holds a component for the step: revise it so the
    // change to content or links is visible as `changed` rather than silent.
    if let Some(component) = find_current_component(
        ctx,
        organization_id,
        &version_artifact_ref(workflow_version_id),
        &component_key_for(&node.node_key),
    ) {
        if component.content_hash != node_hash
            || sorted(&component.decision_ids) != decision_ids
            || sorted(&component.claim_ids) != claim_ids
        {
            revise_ai_artifact_component_inner(
                ctx,
                organization_id,
                company_id,
                component.id,
                ReviseAiArtifactComponentParams {
                    content_hash: node_hash.clone(),
                    fork_artifact_ref: None,
                    fork_component_key: None,
                    decision_ids: Some(decision_ids.clone()),
                    claim_ids: Some(claim_ids.clone()),
                },
            )?;
        }
    }

    write_audit_log_v2(
        ctx,
        organization_id,
        AuditLogParams {
            company_id: Some(company_id),
            table_name: "ai_workflow_node_provenance",
            record_id: row.id,
            action: "CREATE",
            old_values: None,
            new_values: Some(
                serde_json::json!({
                    "workflow_version_id": workflow_version_id,
                    "node_key": row.node_key,
                    "run_id": row.run_id,
                    "decision_ids": row.decision_ids,
                    "claim_ids": row.claim_ids,
                    "node_content_hash": row.node_content_hash,
                })
                .to_string(),
            ),
            changed_fields: vec!["node_key".to_string(), "node_content_hash".to_string()],
            metadata: None,
        },
    );
    Ok(())
}

// ── Hooks used by the workflow definition reducers ───────────────────────────

/// Called by `publish_workflow_version` after the graph validates. A draft with
/// no generation row is human-authored and passes untouched. Otherwise every
/// material step must carry current provenance, and each is bound (or
/// re-verified, when a clone already holds its component). Any `Err` rolls the
/// publication back.
pub(crate) fn enforce_on_publish(
    ctx: &ReducerContext,
    version: &WorkflowVersion,
    nodes: &[WorkflowNode],
) -> Result<(), String> {
    let Some(generation) = find_generation(ctx, version.id) else {
        return Ok(());
    };
    let company_id = generation_company(&generation, version)?;
    let organization_id = version.organization_id;
    let artifact_ref = version_artifact_ref(version.id);

    // Phase one verifies every step without writing anything, so a failing
    // step leaves no partial bindings even before the reducer's own rollback.
    let mut to_bind: Vec<BindAiArtifactComponentParams> = Vec::new();
    for node in nodes {
        let node_hash = canonical_node_hash(node)?;
        let material = is_material_node(&node.kind);
        let Some(staged) = current_staged(ctx, version.id, &node.node_key) else {
            if material {
                return Err(format!(
                    "generated workflow step '{}' has no provenance; stage accepted decisions before publishing",
                    node.node_key
                ));
            }
            continue;
        };
        if staged.node_content_hash != node_hash {
            return Err(format!(
                "generated workflow step '{}' changed after its provenance was staged; restage it",
                node.node_key
            ));
        }
        if staged.run_id != generation.run_id
            || staged.organization_id != organization_id
            || staged.company_id != company_id
        {
            return Err(format!(
                "provenance for step '{}' is outside this workflow's run or tenant",
                node.node_key
            ));
        }
        // Everything can have moved since staging: recheck it all.
        require_step_links_current(
            ctx,
            organization_id,
            company_id,
            &staged.decision_ids,
            &staged.claim_ids,
        )?;

        let component_key = component_key_for(&node.node_key);
        match find_current_component(ctx, organization_id, &artifact_ref, &component_key) {
            None => to_bind.push(BindAiArtifactComponentParams {
                artifact_ref: artifact_ref.clone(),
                component_key,
                component_kind: "workflow_step".to_string(),
                content_hash: node_hash,
                decision_ids: staged.decision_ids.clone(),
                claim_ids: staged.claim_ids.clone(),
            }),
            Some(component) => require_component_publishable(
                ctx,
                &component,
                &node_hash,
                &staged.decision_ids,
                &staged.claim_ids,
            )
            .map_err(|error| format!("generated workflow step '{}': {error}", node.node_key))?,
        }
    }
    // Phase two binds through the shared helper; its own validation is the
    // last word, and any error still rolls the reducer back.
    for params in to_bind {
        bind_ai_artifact_component_inner(ctx, organization_id, company_id, params)?;
    }
    Ok(())
}

/// Called by `clone_workflow_version_to_draft`. A clone of a generated version
/// is itself generated (same run, `parent_workflow_version_id` set), inherits
/// each step's staged provenance, and forks each parent component so ancestry
/// and link state carry forward.
pub(crate) fn carry_generation_to_clone(
    ctx: &ReducerContext,
    source: &WorkflowVersion,
    draft: &WorkflowVersion,
) -> Result<(), String> {
    let Some(generation) = find_generation(ctx, source.id) else {
        return Ok(());
    };
    let company_id = generation_company(&generation, source)?;
    let organization_id = source.organization_id;
    ctx.db
        .ai_workflow_generation()
        .insert(AiWorkflowGeneration {
            id: 0,
            organization_id,
            company_id,
            workflow_version_id: draft.id,
            run_id: generation.run_id,
            parent_workflow_version_id: Some(source.id),
            create_uid: ctx.sender(),
            create_date: ctx.timestamp,
        });

    let source_ref = version_artifact_ref(source.id);
    let draft_ref = version_artifact_ref(draft.id);
    for node in nodes_for_version(ctx, draft.id) {
        let component_key = component_key_for(&node.node_key);
        let Some(parent) =
            find_current_component(ctx, organization_id, &source_ref, &component_key)
        else {
            continue;
        };
        let node_hash = canonical_node_hash(&node)?;
        ctx.db
            .ai_workflow_node_provenance()
            .insert(AiWorkflowNodeProvenance {
                id: 0,
                organization_id,
                company_id,
                workflow_version_id: draft.id,
                draft_revision: draft.draft_revision,
                node_key: node.node_key.clone(),
                run_id: generation.run_id,
                decision_ids: parent.decision_ids.clone(),
                claim_ids: parent.claim_ids.clone(),
                node_content_hash: node_hash.clone(),
                status: STAGED_CURRENT.to_string(),
                create_uid: ctx.sender(),
                create_date: ctx.timestamp,
            });
        revise_ai_artifact_component_inner(
            ctx,
            organization_id,
            company_id,
            parent.id,
            ReviseAiArtifactComponentParams {
                content_hash: node_hash,
                fork_artifact_ref: Some(draft_ref.clone()),
                fork_component_key: Some(component_key),
                decision_ids: None,
                claim_ids: None,
            },
        )?;
    }
    Ok(())
}

/// Called by `delete_workflow_node`: a step that no longer exists must not keep
/// live provenance or a live component.
pub(crate) fn retire_node_provenance(
    ctx: &ReducerContext,
    version: &WorkflowVersion,
    node_key: &str,
) {
    if find_generation(ctx, version.id).is_none() {
        return;
    }
    if let Some(staged) = current_staged(ctx, version.id, node_key) {
        ctx.db
            .ai_workflow_node_provenance()
            .id()
            .update(AiWorkflowNodeProvenance {
                status: STAGED_SUPERSEDED.to_string(),
                ..staged
            });
    }
    if let Some(component) = find_current_component(
        ctx,
        version.organization_id,
        &version_artifact_ref(version.id),
        &component_key_for(node_key),
    ) {
        supersede_component(ctx, component);
    }
}

/// Called before a published version is used (for example to start an
/// instance). A generated version whose steps are no longer all linked to
/// accepted decisions and usable claims cannot be reused until a reviewer has
/// re-confirmed them.
pub(crate) fn require_version_provenance_current(
    ctx: &ReducerContext,
    version: &WorkflowVersion,
) -> Result<(), String> {
    let Some(generation) = find_generation(ctx, version.id) else {
        return Ok(());
    };
    let company_id = generation_company(&generation, version)?;
    let artifact_ref = version_artifact_ref(version.id);
    for node in nodes_for_version(ctx, version.id) {
        if !is_material_node(&node.kind) {
            continue;
        }
        let component = find_current_component(
            ctx,
            version.organization_id,
            &artifact_ref,
            &component_key_for(&node.node_key),
        )
        .ok_or_else(|| {
            format!(
                "generated workflow step '{}' has no bound provenance",
                node.node_key
            )
        })?;
        require_component_publishable(
            ctx,
            &component,
            &canonical_node_hash(&node)?,
            &component.decision_ids,
            &component.claim_ids,
        )
        .map_err(|error| format!("generated workflow step '{}': {error}", node.node_key))?;
        require_step_links_current(
            ctx,
            version.organization_id,
            company_id,
            &component.decision_ids,
            &component.claim_ids,
        )
        .map_err(|error| format!("generated workflow step '{}': {error}", node.node_key))?;
    }
    Ok(())
}

/// A confirmation of a workflow-step component is only valid for the node's
/// current content: the node it names must exist and still hash to exactly the
/// component's content.
pub(crate) fn require_component_matches_workflow_node(
    ctx: &ReducerContext,
    component: &AiArtifactComponent,
) -> Result<(), String> {
    let (version_id, node_key) =
        parse_step_component(&component.artifact_ref, &component.component_key)
            .ok_or("workflow step component has a malformed artifact reference")?;
    let version = ctx
        .db
        .workflow_version()
        .id()
        .find(&version_id)
        .ok_or("workflow version not found")?;
    if version.organization_id != component.organization_id {
        return Err("workflow version does not belong to this organization".to_string());
    }
    let node = ctx
        .db
        .workflow_node()
        .workflow_node_by_version()
        .filter(&version_id)
        .find(|node| node.node_key == node_key)
        .ok_or_else(|| format!("workflow node '{node_key}' no longer exists"))?;
    if canonical_node_hash(&node)? != component.content_hash {
        return Err(format!(
            "workflow node '{node_key}' has changed since this content was staged; restage it"
        ));
    }
    Ok(())
}

// ── Internals ────────────────────────────────────────────────────────────────

fn find_generation(ctx: &ReducerContext, workflow_version_id: u64) -> Option<AiWorkflowGeneration> {
    ctx.db
        .ai_workflow_generation()
        .workflow_version_id()
        .find(&workflow_version_id)
}

fn generation_company(
    generation: &AiWorkflowGeneration,
    version: &WorkflowVersion,
) -> Result<u64, String> {
    if generation.organization_id != version.organization_id
        || version.company_id != Some(generation.company_id)
    {
        return Err("generated workflow provenance is outside the workflow's tenant".to_string());
    }
    Ok(generation.company_id)
}

fn require_generation_scope(
    ctx: &ReducerContext,
    version: &WorkflowVersion,
    organization_id: u64,
    company_id: u64,
) -> Result<AiWorkflowGeneration, String> {
    let generation = find_generation(ctx, version.id)
        .ok_or("the workflow draft has not been marked as harness-generated")?;
    if generation.organization_id != organization_id
        || generation.company_id != company_id
        || version.company_id != Some(company_id)
    {
        return Err("the workflow draft belongs to a different organization/company".to_string());
    }
    Ok(generation)
}

fn current_staged(
    ctx: &ReducerContext,
    workflow_version_id: u64,
    node_key: &str,
) -> Option<AiWorkflowNodeProvenance> {
    ctx.db
        .ai_workflow_node_provenance()
        .ai_workflow_node_provenance_by_version()
        .filter(&workflow_version_id)
        .find(|row| row.node_key == node_key && row.status == STAGED_CURRENT)
}

/// The rules a step's links must meet, shared by staging, publishing and reuse:
/// at least one accepted decision (a bibliography is not enough), current
/// human-reviewed claims, and every dependency usable.
fn require_step_links_current(
    ctx: &ReducerContext,
    organization_id: u64,
    company_id: u64,
    decision_ids: &[u64],
    claim_ids: &[u64],
) -> Result<(), String> {
    validate_component_links(decision_ids, claim_ids)?;
    require_bindable_links(ctx, organization_id, company_id, decision_ids, claim_ids)?;
    require_reviewed_claim_links(ctx, organization_id, company_id, claim_ids)?;
    for decision_id in decision_ids {
        require_dependencies_usable(ctx, organization_id, DependentKind::Decision, *decision_id)?;
    }
    for claim_id in claim_ids {
        // Reload rather than trusting the id list: a claim of another tenant
        // is denied here even if it was ever staged.
        load_claim(ctx, organization_id, company_id, *claim_id)?;
        require_dependencies_usable(ctx, organization_id, DependentKind::Claim, *claim_id)?;
    }
    Ok(())
}

/// An already-bound component (a clone's fork) may publish only when it is
/// linked, still describes exactly the node's content and staged links, and
/// its own dependencies are usable.
fn require_component_publishable(
    ctx: &ReducerContext,
    component: &AiArtifactComponent,
    node_hash: &str,
    decision_ids: &[u64],
    claim_ids: &[u64],
) -> Result<(), String> {
    if component.content_hash != node_hash {
        return Err(
            "its component no longer matches the node's content; restage and re-review it"
                .to_string(),
        );
    }
    if sorted(&component.decision_ids) != sorted(decision_ids)
        || sorted(&component.claim_ids) != sorted(claim_ids)
    {
        return Err("its component links differ from the staged provenance".to_string());
    }
    if component.link_state != LINK_LINKED {
        return Err(format!(
            "its component links are {}; an authorized reviewer must confirm them first",
            component.link_state
        ));
    }
    require_dependencies_usable(
        ctx,
        component.organization_id,
        DependentKind::Component,
        component.id,
    )
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn component_identity_round_trips() {
        let artifact = version_artifact_ref(42);
        let key = component_key_for("approve-invoice");
        assert_eq!(artifact, "workflow-version:42");
        assert_eq!(key, "node:approve-invoice");
        assert_eq!(
            parse_step_component(&artifact, &key),
            Some((42, "approve-invoice".to_string()))
        );
    }

    #[test]
    fn malformed_step_components_do_not_parse() {
        assert_eq!(parse_step_component("presentation:1", "node:a"), None);
        assert_eq!(parse_step_component("workflow-version:x", "node:a"), None);
        assert_eq!(parse_step_component("workflow-version:1", "a"), None);
        assert_eq!(parse_step_component("workflow-version:1", "node:"), None);
    }

    #[test]
    fn only_routing_steps_are_immaterial() {
        for kind in [
            WorkflowNodeKind::Start,
            WorkflowNodeKind::End,
            WorkflowNodeKind::Fork,
            WorkflowNodeKind::Join,
        ] {
            assert!(!is_material_node(&kind));
        }
        for kind in [
            WorkflowNodeKind::Decision,
            WorkflowNodeKind::HumanTask,
            WorkflowNodeKind::Action,
            WorkflowNodeKind::Timer,
            WorkflowNodeKind::Subflow,
        ] {
            assert!(is_material_node(&kind));
        }
    }

    #[test]
    fn link_comparison_ignores_order() {
        assert_eq!(sorted(&[3, 1, 2]), sorted(&[2, 3, 1]));
    }
}
